using System.Text;

public static class Program
{
    public static void Main()
    {
        Dispatcher dispatcher = new();
        Console.OutputEncoding = Encoding.UTF8;
        dispatcher.Work();
    }
}

public class WarriorFabric
{
    public List<Warrior> Create()
    {
        List<Warrior> warriors =
        [
            new Luckier(15, 90),
            new Monk(10, 100),
            new Berserk(3, 300),
            new Magican(7, 80, 20),
            new Thief(15, 50),
        ];

        return warriors;
    }
}


public class Dispatcher
{
    private List<Warrior> _warriors;

    public Dispatcher() =>
        _warriors = new WarriorFabric().Create();

    public void Work()
    {
        const string GreetingsChoise = "1";
        const string LookFightChoise = "2";
        const string ExitChoise = "3";

        bool isWork = true;

        while (isWork)
        {
            Console.Clear();
            string userChoise = Utils.GetUserInput($"\n{GreetingsChoise}) Приветственное сообщение\n" +
                $"{LookFightChoise}) Посмотреть бой\n{ExitChoise}) Выход\n");

            switch (userChoise)
            {
                case GreetingsChoise:
                    ShowGreetings();
                    break;

                case LookFightChoise:
                    LookFight();
                    break;

                case ExitChoise:
                    isWork = false;
                    break;
            }
        }
    }

    private void ShowGreetings()
    {
        Console.Clear();
        Console.WriteLine("Добро пожаловать в колизей");
        Console.ReadKey();
    }

    private bool ChoiseWarrior(Warrior warrior)
    {
        const string ChoiseWarriorCommand = "1";
        const string ReturnCommand = "2";

        Console.Clear();
        Console.WriteLine(warrior.AskiiImage);
        Console.WriteLine("\n" + warrior.GetInfo());
        string choise = Utils.GetUserInput($"\nВыбрать этого бойца?\nДа - {ChoiseWarriorCommand}\nНет - {ReturnCommand}");
        if (choise == ChoiseWarriorCommand)
            return true;
        else
            return false;
    }

    private void ShowAllWarriors()
    {
        for (int i = 0; i < _warriors.Count; i++)
        {
            Console.WriteLine($"{i + 1}){_warriors[i].Name}");
        }
    }

    private void LookFight()
    {
        Console.Clear();
        ChoiseWarriors(out Warrior warrior1, out Warrior warrior2);
        bool isFirstAttack = true;

        while (warrior1.IsLive && warrior2.IsLive)
        {
            Console.Clear();
            warrior1.ClearMessage();
            warrior2.ClearMessage();

            if (isFirstAttack)
            {
                warrior1.Attack(warrior2);
                isFirstAttack = false;
            }
            else
            {
                warrior2.Attack(warrior1);
                isFirstAttack = true;
            }

            ShowFighing(warrior1, warrior2);
            Console.ReadKey();
        }
    }

    private void ChoiseWarriors(out Warrior warrior1, out Warrior warrior2)
    {
        warrior1 = null;
        while (warrior1 == null)
        {
            Console.Clear();
            Console.WriteLine("Выбери первого бойца");
            ShowAllWarriors();

            if (Utils.GetNumFromUser(out int num))
                if (ChoiseWarrior(_warriors[num - 1]))
                    warrior1 = _warriors[num - 1].Clone();
        }

        warrior2 = null;
        while (warrior2 == null)
        {
            Console.Clear();
            Console.WriteLine("Выбери второго бойца");
            ShowAllWarriors();

            if (Utils.GetNumFromUser(out int num))
                if (ChoiseWarrior(_warriors[num - 1]))
                    warrior2 = _warriors[num - 1].Clone();
        }
    }

    private void ShowFighing(Warrior warrior1, Warrior warrior2)
    {
        const string imageBetweenDistance = "\t\t\t\t\t\t\t";
        string doubleImages = "";
        string[] firstWarriorImage = warrior1.AskiiImage.Split("\r\n");
        string[] secondWarriorImage = warrior2.AskiiImage.Split("\r\n");
        int length = Math.Max(firstWarriorImage.Length, secondWarriorImage.Length);

        Console.WriteLine($"Здоровье {warrior1.Name}: {warrior1.Health}\nПоследнее событие - {warrior1.Message}\n");
        Console.WriteLine($"Здоровье {warrior2.Name}: {warrior2.Health}\nПоследнее событие - {warrior2.Message}");

        for (int i = 0; i < length; i++)
        {
            string firstString = i < firstWarriorImage.Length ? firstWarriorImage[i] : new string(' ', firstWarriorImage[0].Length);
            string secondString = i < secondWarriorImage.Length ? secondWarriorImage[i] : "";

            Console.WriteLine($"{firstString}{imageBetweenDistance}{secondString}");
        }
    }

}

public interface IDamagable
{
    public void TakeDamage(int damage);
}

public abstract class Warrior : IDamagable
{
    protected int _damage;
    protected int _maxHealth;

    protected string _askiiAttackImage;
    protected string _askiiSpecialImage;
    protected string _askiiTakeDamageImage;
    protected string _askiiDeadImage;
    protected string _askiiIdleImage;
    protected string _normalAttackMessage;
    protected string _specialMessage;
    protected string _takeDamageMessage;
    protected string _deadMessage;
    protected string _insertedPointInMessages;

    public Warrior(int damage, int maxHealth)
    {
        _damage = damage;
        _maxHealth = maxHealth;
        _insertedPointInMessages = "#";

        Health = maxHealth;
        IsLive = true;
        SetImages();
        SetMessages();
        AskiiImage = _askiiIdleImage;
        Message = "";
    }

    public string Name { get; protected set; }
    public string AbilityDescription { get; protected set; }
    public string Phrase { get; protected set; }
    public string AskiiImage { get; protected set; }
    public string Message { get; protected set; }
    public int Health { get; protected set; }
    public bool IsLive { get; protected set; }

    public virtual void Attack(IDamagable enemy)
    {
        int damage = GetDamage();
        enemy.TakeDamage(damage);
        AskiiImage = _askiiAttackImage;
        Message += InsertInfoInString(_normalAttackMessage, damage.ToString());
    }

    public virtual void TakeDamage(int damage)
    {
        Health -= damage;

        if (Health <= 0)
        {
            Health = 0;
            AskiiImage = _askiiDeadImage;
            Message += InsertInfoInString(_deadMessage, damage.ToString());
            IsLive = false;
            return;
        }

        AskiiImage = _askiiSpecialImage;
        Message += InsertInfoInString(_takeDamageMessage, damage.ToString());
    }

    public Warrior Clone()
    {
        return (Warrior)MemberwiseClone();
    }

    public void ClearMessage() =>
        Message = "";

    public virtual string GetInfo()
    {
        return $"Имя - {Name}\nЛюбимая фраза - {Phrase}\nОсобенность - {AbilityDescription}" +
            $"\nСредний урон - {_damage}\nМаксимальное здоровье - {_maxHealth}";
    }

    protected int GetDamage()
    {
        int maxDifference = _damage / 3;
        int damageModifire = Utils.Random.Next(maxDifference * -1, maxDifference);
        return _damage + damageModifire;
    }

    protected string InsertInfoInString(string str, string info)
    {
        string needString = new(str);
        needString = needString.Replace(_insertedPointInMessages, info) + " ";
        return needString;
    }

    protected abstract void SetImages();
    protected abstract void SetMessages();
}

public class Luckier : Warrior
{
    private double _specialAttackChance = 0.5;

    public Luckier(int damage, int maxHealth)
        : base(damage, maxHealth)
    {
        Name = "Красавчик Джек";
        AbilityDescription = "С вероятностью 50/50 нанесёт двойной урон";
        Phrase = "Вы бандиты. Вы плохие парни. А Я, ЧЁРТ ВОЗЬМИ, ГЕРОЙ!";
    }

    public override void Attack(IDamagable enemy)
    {
        if (Utils.Random.NextDouble() > _specialAttackChance)
        {
            int damage = GetDamage() * 2;
            enemy.TakeDamage(damage);
            AskiiImage = _askiiSpecialImage;
            Message += InsertInfoInString(_specialMessage, damage.ToString());
        }
        else
