public class Monk : Warrior
{
    private int _maxAttackCountToSpecial = 3;
    private int _attackCountToSpecial = 0;

    public Monk(int damage, int maxHealth)
        : base(damage, maxHealth)
    {
        Name = "Иисус христос";
        AbilityDescription = "Дважды атакует каждую третью атаку";
        Phrase = "Если тебя ударили, то подставь вторую щёку. А на третий раз вьеби";
    }

    public override void Attack(IDamagable enemy)
    {
        _attackCountToSpecial++;

        if (_attackCountToSpecial >= _maxAttackCountToSpecial)
        {
            int damage = GetDamage();
            enemy.TakeDamage(damage);
            enemy.TakeDamage(damage);

            AskiiImage = _askiiSpecialImage;
            _attackCountToSpecial = 0;
            Message += InsertInfoInString(_specialMessage, damage.ToString());
        }
        else
        {
            base.Attack(enemy);
        }
    }

