public class Berserk : Warrior
{
    private int _maxDamageCountToHeal = 300;
    private int _damageCountToHeal = 0;
    private int _damageTakingBonus = 30;

    public Berserk(int damage, int maxHealth)
        : base(damage, maxHealth)
    {
        Name = "Гатс";
        AbilityDescription = "Каждое ранение копит ярость. При накоплении максимума - лечится по схеме урон * 2";
        Phrase = "Сначала потерплю-потерплю, а потом каааааак потерплю-потерплю";
        AskiiImage = _askiiIdleImage;
    }

    public override void TakeDamage(int damage)
    {
        _damageCountToHeal += damage + _damageTakingBonus;

        if (_damageCountToHeal >= _maxDamageCountToHeal)
        {
            Heal(damage * 2);
            AskiiImage = _askiiSpecialImage;
            return;
        }

        base.TakeDamage(damage);
    }

    private void Heal(int healCount)
    {
        if (Health + healCount > _maxHealth)
            Health = _maxHealth;
        else
            Health += healCount;

        Message += InsertInfoInString(_specialMessage, healCount.ToString());
    }

    public override string GetInfo()
    {
        return base.GetInfo() + $"\nМаксимально полученный урон до ярости - {_maxDamageCountToHeal}\n" +
            $"Добавка к ярости от каждого урона - {_damageTakingBonus}\n";
    }

