    protected override void SetMessages()
    {
        _normalAttackMessage = $"Выместил злобу, нанеся {_insertedPointInMessages} урона";
        _specialMessage = $"Ярость дала сил, вылечившись на {_insertedPointInMessages} едениц";
        _takeDamageMessage = $"Получил дрова в топку ярости на {_insertedPointInMessages} едениц";
        _deadMessage = $"Временно убит, получив {_insertedPointInMessages} едениц урона";
    }
}

public class Magican : Warrior
{
    private int _manaCount = 100;
    private int _needManaToFireball = 20;
    private int _fireballDamage = 20;

    public Magican(int damage, int maxHealth, int fireballDamage)
        : base(damage, maxHealth)
    {
        Name = "Кэяру";
        AbilityDescription = "Пока есть мана, атакует файрболами";
        Phrase = "Лечение";
        _fireballDamage = fireballDamage;
    }

    public override void Attack(IDamagable enemy)
    {
        if (_manaCount >= _needManaToFireball)
        {
            _manaCount -= _needManaToFireball;
            enemy.TakeDamage(_fireballDamage);
            AskiiImage = _askiiSpecialImage;
            Message += InsertInfoInString(_specialMessage, _fireballDamage.ToString());
            return;
        }

        base.Attack(enemy);
    }

    public override string GetInfo()
    {
        return base.GetInfo() + $"\nКоличество маны: - {_manaCount}\n" +
            $"Необходимое количество маны на один файрбол - {_needManaToFireball}\n" +
            $"Среднйи урон от файрбола - {_fireballDamage}\n";
    }
