public class Thief : Warrior
{
    private double _dodgeChance = 0.5;

    public Thief(int damage, int maxHealth) : base(damage, maxHealth)
    {
        Name = "Корво Аттано";
        AbilityDescription = "С вероятностью 50% увернётся от удара";
        Phrase = "С девушками надо быть нежнее";
    }

    public override void TakeDamage(int damage)
    {
        if (Utils.Random.NextDouble() > _dodgeChance)
        {
            AskiiImage = _askiiSpecialImage;
            Message += InsertInfoInString(_specialMessage, damage.ToString());
        }
        else
        {
            base.TakeDamage(damage);
        }
    }

